@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

:root {
  /* Pillow Light — light theme, vivid cobalt primary, pillow-soft 3D buttons */

  --background: #FFFFFF;
  --foreground: #0F172A;

  --card: #FFFFFF;
  --card-foreground: #0F172A;

  --popover: #FFFFFF;
  --popover-foreground: #0F172A;

  /* Brand blue — vivid, saturated cobalt */
  --primary: #1E66FF;
  --primary-foreground: #FFFFFF;

  /* Light off-white surface used for the secondary CTA */
  --secondary: #F4F5F7;
  --secondary-foreground: #0F172A;

  --muted: #F4F5F7;
  --muted-foreground: #5B6573;

  --accent: #EEF2FF;
  --accent-foreground: #1E66FF;

  --destructive: #E11D48;
  --destructive-foreground: #FFFFFF;

  --border: #E5E7EB;
  --input: #FFFFFF;
  --ring: #1E66FF;

  --radius: 0.875rem; /* 14px — pillowed pill shape */

  /* Pillow-shadow tokens — used by Button and other elevated surfaces */
  --shadow-pillow-primary:
    inset 0 1px 0 0 rgba(255, 255, 255, 0.30),
    inset 0 -2px 0 0 rgba(0, 0, 0, 0.18),
    0 1px 1px 0 rgba(15, 23, 42, 0.08),
    0 4px 10px -2px rgba(30, 102, 255, 0.35);
  --shadow-pillow-primary-hover:
    inset 0 1px 0 0 rgba(255, 255, 255, 0.32),
    inset 0 -2px 0 0 rgba(0, 0, 0, 0.20),
    0 2px 2px 0 rgba(15, 23, 42, 0.10),
    0 8px 18px -3px rgba(30, 102, 255, 0.45);
  --shadow-pillow-secondary:
    inset 0 1px 0 0 rgba(255, 255, 255, 1),
    inset 0 -1.5px 0 0 rgba(15, 23, 42, 0.06),
    0 0 0 1px rgba(15, 23, 42, 0.05),
    0 1px 1px 0 rgba(15, 23, 42, 0.04),
    0 3px 8px -2px rgba(15, 23, 42, 0.10);
  --shadow-pillow-secondary-hover:
    inset 0 1px 0 0 rgba(255, 255, 255, 1),
    inset 0 -1.5px 0 0 rgba(15, 23, 42, 0.08),
    0 0 0 1px rgba(15, 23, 42, 0.07),
    0 2px 2px 0 rgba(15, 23, 42, 0.06),
    0 6px 14px -3px rgba(15, 23, 42, 0.14);

  /* Subtle elevation tokens — borrows pillow vocabulary, lighter for cards/popovers */
  --shadow-2xs: 0 1px 1px rgba(15, 23, 42, 0.04);
  --shadow-xs:  0 1px 2px rgba(15, 23, 42, 0.05);
  --shadow-sm:  0 1px 2px rgba(15, 23, 42, 0.06), 0 2px 6px rgba(15, 23, 42, 0.04);
  --shadow:     0 1px 2px rgba(15, 23, 42, 0.06), 0 4px 12px rgba(15, 23, 42, 0.06);
  --shadow-md:  0 2px 4px rgba(15, 23, 42, 0.06), 0 8px 20px rgba(15, 23, 42, 0.08);
  --shadow-lg:  0 4px 12px rgba(15, 23, 42, 0.08), 0 16px 32px rgba(15, 23, 42, 0.10);
  --shadow-xl:  0 8px 24px rgba(15, 23, 42, 0.12), 0 0 0 1px rgba(15, 23, 42, 0.04);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: calc(var(--radius) - 6px);
  --radius-md: calc(var(--radius) - 4px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    font-family: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    -webkit-font-smoothing: antialiased;
    letter-spacing: -0.011em;
  }
  body {
    @apply bg-background text-foreground antialiased;
  }
}
